    env = _from_glom_import_star()
    env['T'] = glom.T
    code = _compile_code(py_text, '<spec>', env, verbose=False)
    return eval(code, env)

def _compile_code(code_str, name, env=None, verbose=False):
    if env is None:
        env = {}
    try:
        code = compile(code_str, name, 'eval')
        return code
    except SyntaxError as se:
        raise CommandLineError(f'syntax error in {name}: {se}')
